I currently have an operator's aten ir and want to return both in-place and non-in-place operation parameters at the same time. How should I define the aten ir? Can it be defined in the following way?
func: test_op(Tensor a, Tensor b, Tensor c, Tensor d, Tensor(a!) e, Tensor(b!) f, *, Tensor? g=None, Tensor? h=None) -> (Tensor, Tensor, Tensor(a!), Tensor(b!))
@cpuhrsch

🐛 Describe the bug
When using from torch.utils.cpp_extension import load_inline to compile an inline CUDA extension, the NVCC command line automatically includes a series of legacy -gencode=arch=compute_XY,code=sm_XY flags (e.g. compute_52, compute_60, etc.). Even if I specify only the latest architecture in extra_cuda_cflags, these old flags remain, so Tensor Core instructions or other newer hardware features are not enabled in the resulting binary.
Reproduction Steps


Install PyTorch 2.5.1 with CUDA 12.1


Create a minimal example calling load_inline
import torch
import torch.nn as nn


class Model(nn.Module):
    """
    Performs batched matrix multiplication (C = A * B) where A, B, and C have the same batch dimension.
    """

    def __init__(self):
        super(Model, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs batched matrix multiplication.

        Args:
            A: Input tensor of shape (batch_size, m, k).
            B: Input tensor of shape (batch_size, k, n).

        Returns:
            C: Output tensor of shape (batch_size, m, n).
        """
        return torch.bmm(A, B)


batch_size = 128
m = 128
k = 256
n = 512


def get_inputs():
    A = torch.randn(batch_size, m, k, dtype=torch.float32)
    B = torch.randn(batch_size, k, n, dtype=torch.float32)
    return [A, B]


def get_init_inputs():
    return []  # No special initialization inputs needed


def get_ref():
    model = Model()
    return model


# %%
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_custom_bmm_extension = None


def _load_custom_bmm_extension():
    global _custom_bmm_extension
    if _custom_bmm_extension is not None:
        return _custom_bmm_extension

    cuda_source = r"""
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>
#include <mma.h>
#include <ATen/ATen.h>

using namespace nvcuda::wmma;

template <typename T>
__global__ void batched_matmul_kernel(const T* __restrict__ A, const T* __restrict__ B, T* C,
                                    int batch_size, int m, int n, int k) {
    const int tile_size = 16;
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int bz = blockIdx.z;

    if (bz >= batch_size || by * tile_size >= m || bx * tile_size >= n) 
        return;

    __shared__ __align__(16) half A_tile[tile_size][tile_size + 1];
    __shared__ __align__(16) half B_tile[tile_size][tile_size + 1];

    nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, tile_size, tile_size, tile_size, half, nvcuda::wmma::row_major> a_frag;
    nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, tile_size, tile_size, tile_size, half, nvcuda::wmma::col_major> b_frag;
    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, tile_size, tile_size, tile_size, float> acc_frag;

    nvcuda::wmma::fill_fragment(acc_frag, 0.0f);

    for (int tile_k = 0; tile_k < k; tile_k += tile_size) {
        for (int i = threadIdx.y; i < tile_size; i += blockDim.y) {
            int rowA = by * tile_size + i;
            int colA = tile_k + threadIdx.x;

            if (rowA < m && colA < k) {
                A_tile[i][threadIdx.x] = __float2half((float)A[bz * m * k + rowA * k + colA]);
            } else {
                A_tile[i][threadIdx.x] = __float2half(0.0f);
            }

            int rowB = tile_k + i;
            int colB = bx * tile_size + threadIdx.x;

            if (rowB < k && colB < n) {
                B_tile[i][threadIdx.x] = __float2half((float)B[bz * k * n + rowB * n + colB]);
            } else {
                B_tile[i][threadIdx.x] = __float2half(0.0f);
            }
        }
        __syncthreads();

        nvcuda::wmma::load_matrix_sync(a_frag, &A_tile[0][0], tile_size + 1);
        nvcuda::wmma::load_matrix_sync(b_frag, &B_tile[0][0], tile_size + 1);
        nvcuda::wmma::mma_sync(acc_frag, a_frag, b_frag, acc_frag);
        __syncthreads();
    }

    __shared__ __align__(16) float C_buffer[tile_size][tile_size];
    nvcuda::wmma::store_matrix_sync(&C_buffer[0][0], acc_frag, tile_size, nvcuda::wmma::mem_row_major);
    __syncthreads();

    for (int i = threadIdx.y; i < tile_size; i += blockDim.y) {
        int rowC = by * tile_size + i;
        int colC = bx * tile_size + threadIdx.x;

        if (rowC < m && colC < n) {
            C[bz * m * n + rowC * n + colC] = static_cast<T>(C_buffer[i][threadIdx.x]);
        }
    }
}

template <>
__global__ void batched_matmul_kernel<float>(const float* __restrict__ A, const float* __restrict__ B, float* C,
                                            int batch_size, int m, int n, int k) {
    const int tile_size = 32;
    extern __shared__ __align__(16) float shared[];

    float* A_tile = shared;
    float* B_tile = shared + tile_size * tile_size;

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int bz = blockIdx.z;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float sum = 0.0f;
    int row = by * tile_size + ty;
    int col = bx * tile_size + tx;

    for (int tile_k = 0; tile_k < k; tile_k += tile_size) {
        int load_row = row;
        int load_col = tile_k + tx;
        if (load_row < m && load_col < k) {
            A_tile[ty * tile_size + tx] = A[bz * m * k + load_row * k + load_col];
        } else {
            A_tile[ty * tile_size + tx] = 0.0f;
        }

        load_row = tile_k + ty;
        load_col = col;
        if (load_row < k && load_col < n) {
            B_tile[ty * tile_size + tx] = B[bz * k * n + load_row * n + load_col];
        } else {
            B_tile[ty * tile_size + tx] = 0.0f;
        }
        __syncthreads();

        for (int i = 0; i < tile_size; i++) {
            sum += A_tile[ty * tile_size + i] * B_tile[i * tile_size + tx];
        }
        __syncthreads();
    }

    if (row < m && col < n) {
        C[bz * m * n + row * n + col] = sum;
    }
}

template <typename T>
void batched_matmul_dispatch(const torch::Tensor& A, const torch::Tensor& B, torch::Tensor& C,
                            int batch_size, int m, int n, int k) {
    dim3 grid((n + 15) / 16, (m + 15) / 16, batch_size);
    dim3 block(16, 16, 1);

    if (std::is_same<T, float>::value) {
        grid = dim3((n + 31) / 32, (m + 31) / 32, batch_size);
        block = dim3(32, 32, 1);
    }

    const T* A_ptr = A.data_ptr<T>();
    const T* B_ptr = B.data_ptr<T>();
    T* C_ptr = C.data_ptr<T>();

    size_t shared_mem = (std::is_same<T, float>::value) ? 2 * 32 * 32 * sizeof(float) : 0;

    batched_matmul_kernel<T><<<grid, block, shared_mem>>>(
        A_ptr, B_ptr, C_ptr, batch_size, m, n, k
    );
}

void batched_matmul_dispatch_half(const torch::Tensor& A, const torch::Tensor& B, torch::Tensor& C, int batch_size, int m, int n, int k) {
    batched_matmul_dispatch<at::Half>(A, B, C, batch_size, m, n, k);
}

void batched_matmul_dispatch_bf16(const torch::Tensor& A, const torch::Tensor& B, torch::Tensor& C, int batch_size, int m, int n, int k) {
    batched_matmul_dispatch<at::BFloat16>(A, B, C, batch_size, m, n, k);
}

void batched_matmul_dispatch_fp32(const torch::Tensor& A, const torch::Tensor& B, torch::Tensor& C, int batch_size, int m, int n, int k) {
    batched_matmul_dispatch<float>(A, B, C, batch_size, m, n, k);
}
