    cpp_source = r"""
#include <torch/extension.h>

extern "C" void batched_matmul_dispatch_half(const torch::Tensor& A, const torch::Tensor& B, torch::Tensor& C, int batch_size, int m, int n, int k);

extern "C" void batched_matmul_dispatch_bf16(const torch::Tensor& A, const torch::Tensor& B, torch::Tensor& C, int batch_size, int m, int n, int k);

extern "C" void batched_matmul_dispatch_fp32(const torch::Tensor& A, const torch::Tensor& B, torch::Tensor& C, int batch_size, int m, int n, int k);

void batched_matmul(const torch::Tensor& A, const torch::Tensor& B, torch::Tensor& C) {
    TORCH_CHECK(A.device().is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.device().is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 3, "A must be 3D");
    TORCH_CHECK(B.dim() == 3, "B must be 3D");

    int batch_size = A.size(0);
    int m = A.size(1);
    int k = A.size(2);
    int n = B.size(2);

    TORCH_CHECK(B.size(0) == batch_size, "batch size mismatch");
    TORCH_CHECK(B.size(1) == k, "matrix dimension mismatch");

    C = torch::empty({batch_size, m, n}, A.options());

    if (A.scalar_type() == torch::kFloat16) {
        batched_matmul_dispatch_half(A, B, C, batch_size, m, n, k);
    } else if (A.scalar_type() == torch::kBFloat16) {
        batched_matmul_dispatch_bf16(A, B, C, batch_size, m, n, k);
    } else if (A.scalar_type() == torch::kFloat32) {
        batched_matmul_dispatch_fp32(A, B, C, batch_size, m, n, k);
    } else {
        TORCH_CHECK(false, "Unsupported data type");
    }
}
"""

    try:
        extra_cflags = ["-O3", "--fast-math"]
        extra_cuda_cflags = [
            "-I/usr/local/cuda-12.1/include", 
            "--expt-relaxed-constexpr",
            "-arch=sm_80",
            "-gencode=arch=compute_80,code=sm_80",
            "--extended-lambda",
            "-Xptxas=-v",
            "--use_fast_math",
            "-lineinfo",
        ]

        # _custom_bmm_extension = load_inline(
        #     name="custom_bmm",
        #     cpp_sources=cpp_source,
        #     cuda_sources=cuda_source,
        #     functions=["batched_matmul"],
        #     extra_cflags=extra_cflags,
        #     extra_cuda_cflags=extra_cuda_cflags,
        #     verbose=False,
        # )
        _custom_bmm_extension = load_inline(
            name="custom_bmm",
            cpp_sources=cpp_source,
            cuda_sources=cuda_source,
            functions=["batched_matmul"],
            extra_cflags=extra_cflags,
            extra_cuda_cflags=extra_cuda_cflags,
            verbose=False,
        )
    except Exception as e:
        print(f"Custom BMM extension compilation failed: {e}")
        _custom_bmm_extension = None

    return _custom_bmm_extension


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        # !Force force it to use custom kernel
        self.custom_bmm_extension = _load_custom_bmm_extension()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Validate input dimensions
        if A.dim() != 3 or B.dim() != 3:
            return torch.bmm(A, B)

        batch_size, m, k = A.shape
        b_batch, k_in, n = B.shape

        if batch_size != b_batch or k != k_in:
            return torch.bmm(A, B)

        # Check if custom kernel can be used
        if not A.is_cuda or not B.is_cuda:
            return torch.bmm(A, B)

        dtype = A.dtype
        if dtype not in [torch.float16, torch.bfloat16, torch.float32]:
            return torch.bmm(A, B)

        # Small matrix fallback
        if m < 16 or n < 16 or k < 16:
            return torch.bmm(A, B)

        # Ensure contiguous tensors
        A_cont = A.contiguous()
        B_cont = B.contiguous()

        # Create output tensor
        C = torch.empty((batch_size, m, n), dtype=dtype, device=A.device)

        # Execute custom kernel
        self.custom_bmm_extension.batched_matmul(A_cont, B_cont, C)
        return C


